  missing_crds=1
fi
if ! kubectl get crd/cephcosidrivers.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephfilesystemmirrors.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephfilesystems.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephfilesystemsubvolumegroups.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephnfses.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephnvmeofgateways.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephobjectrealms.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephobjectstores.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephobjectstoreusers.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephobjectzonegroups.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephobjectzones.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/cephrbdmirrors.ceph.rook.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/objectbucketclaims.objectbucket.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/objectbuckets.objectbucket.io >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  say "A CRD is missing, so apply the file's CRDs first"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="were applied first"
elif kubectl diff --server-side -f "$work/crds" >/dev/null 2>&1; then
  say "The CRDs already exist and match this file. The script leaves them under their current owner"
  crd_outcome="already existed and matched, so the script left them alone"
elif [ "${APPLY_CRDS:-0}" = "1" ]; then
  say "The existing CRDs differ from this file. APPLY_CRDS=1 is set, so the script applies the file's CRDs"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="differed and were applied, because APPLY_CRDS=1 was set"
else
  say "The CRDs already exist and differ from this file, or another tool owns them"
  cat <<'EOF_CRDS'
This script does not change CRDs it did not just create.
If this is an upgrade, the objects that follow may need the newer CRDs.
To let this script apply the file's CRDs, re-run with:
  APPLY_CRDS=1 bash try-objects.sh
EOF_CRDS
  exit 1
fi
wait_for_crd cephconnections.csi.ceph.io
wait_for_crd clientprofiles.csi.ceph.io
wait_for_crd clientprofilemappings.csi.ceph.io
wait_for_crd drivers.csi.ceph.io
wait_for_crd operatorconfigs.csi.ceph.io
wait_for_crd cephblockpoolradosnamespaces.ceph.rook.io
wait_for_crd cephblockpools.ceph.rook.io
wait_for_crd cephbucketnotifications.ceph.rook.io
wait_for_crd cephbuckettopics.ceph.rook.io
wait_for_crd cephclients.ceph.rook.io
wait_for_crd cephclusters.ceph.rook.io
wait_for_crd cephcosidrivers.ceph.rook.io
wait_for_crd cephfilesystemmirrors.ceph.rook.io
wait_for_crd cephfilesystems.ceph.rook.io
wait_for_crd cephfilesystemsubvolumegroups.ceph.rook.io
wait_for_crd cephnfses.ceph.rook.io
wait_for_crd cephnvmeofgateways.ceph.rook.io
wait_for_crd cephobjectrealms.ceph.rook.io
wait_for_crd cephobjectstores.ceph.rook.io
wait_for_crd cephobjectstoreusers.ceph.rook.io
wait_for_crd cephobjectzonegroups.ceph.rook.io
wait_for_crd cephobjectzones.ceph.rook.io
wait_for_crd cephrbdmirrors.ceph.rook.io
wait_for_crd objectbucketclaims.objectbucket.io
